#ifndef NOAHMP_TEST_UTIL_H
#define NOAHMP_TEST_UTIL_H

// ---------------------------------------------------------------------------
// Minimal assertion helpers for the Noah-MP ERF-driver regression tests.
//
// Deliberately dependency-free (no GoogleTest): each test is a small executable
// that returns 0 on success and non-zero on the first failed check, which is
// exactly what CTest consumes. Keeping this header-only matches the repo's
// minimal-dependency style (the coupling glue itself is generated by a
// stdlib-only Python script).
//
// CHECK(cond)              -- fail unless cond is true
// CHECK_EQ(a, b)           -- fail unless a == b (integers / exact values)
// CHECK_CLOSE(a, b, tol)   -- fail unless |a - b| <= tol (floating point)
// ---------------------------------------------------------------------------

#include <cstdio>
#include <cstdlib>
#include <cmath>

namespace noahmp_test {

inline int& failure_count() {
    static int n = 0;
    return n;
}

inline void report(bool ok, const char* expr, const char* file, int line) {
    if (!ok) {
        std::fprintf(stderr, "  FAIL: %s  (%s:%d)\n", expr, file, line);
        ++failure_count();
    }
}

} // namespace noahmp_test

#define CHECK(cond) \
    ::noahmp_test::report((cond), #cond, __FILE__, __LINE__)

#define CHECK_EQ(a, b) \
    ::noahmp_test::report((a) == (b), #a " == " #b, __FILE__, __LINE__)

#define CHECK_CLOSE(a, b, tol) \
    ::noahmp_test::report(std::fabs(double((a)) - double((b))) <= double(tol), \
                          #a " ~= " #b, __FILE__, __LINE__)

// Print a one-line summary and return a process exit code (0 = all passed).
#define TEST_SUMMARY(name)                                                   \
    do {                                                                     \
        const int _f = ::noahmp_test::failure_count();                       \
        if (_f == 0) std::fprintf(stderr, "PASS: %s\n", (name));             \
        else         std::fprintf(stderr, "FAILED: %s (%d check(s))\n",      \
                                  (name), _f);                               \
        return _f == 0 ? 0 : 1;                                              \
    } while (0)

#endif // NOAHMP_TEST_UTIL_H
